using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using WindowsGameRuntimeASUSSelfHealing.WinUI.Services;
namespace WindowsGameRuntimeASUSSelfHealing.WinUI.Pages;
public sealed partial class IdentityPage:Page{
 private readonly BackendService _backend=App.Services.Backend;private bool _loaded;
 public IdentityPage(){InitializeComponent();Loaded+=async(_,_)=>{if(_loaded)return;_loaded=true;await RefreshAsync();};}
 private async void RefreshButton_Click(object sender,RoutedEventArgs e)=>await RefreshAsync();
 private async Task RefreshAsync(){RefreshButton.IsEnabled=false;Info.Title="后台计算中";try{using var r=await _backend.RunAsync("IDENTITY",timeout:TimeSpan.FromMinutes(4));if(!r.Success)throw new InvalidOperationException(r.Error);var incidents=r.Payload.Array("Incidents").Select(x=>x.Clone()).ToArray();await App.Services.StateStore.UpsertIncidentsAsync(incidents);var lines=new List<string>{"=== Correlated Incidents ==="};foreach(var x in incidents)lines.Add($"[{x.String("Confidence")} score={x.String("Score")}] {x.String("Code")} {x.String("Component")} Profile={x.String("Profile")} | {x.String("Evidence")}");lines.Add("");lines.Add("=== Component Fingerprints ===");foreach(var f in r.Payload.Array("Fingerprints")){lines.Add($"{f.String("Key")} | identityHash={f.String("IdentityHash")}");lines.Add($"  Profile={f.String("ProfileID")} Product={f.String("ProductCode")} Upgrade={f.String("UpgradeCode")}");if(f.TryGetProperty("TargetInstaller",out var ti))lines.Add($"  Target={ti.String("Path")}");}Output.Text=string.Join("\r\n",lines);Info.Title="加载完成";Info.Message="未知/变化的身份会降级为人工确认，不会自动套用旧规则。";Info.Severity=InfoBarSeverity.Success;}catch(Exception ex){Info.Title="加载失败";Info.Message=ex.Message;Info.Severity=InfoBarSeverity.Error;}finally{RefreshButton.IsEnabled=true;}}
}
